/// A cheap content signature over the projection — what changes when an edit lands, and nothing else.
///
/// This is what makes the 5-second poll affordable. The frontend hook already computes a signature to
/// decide whether to re-render, but it did so AFTER receiving the whole document, so the common case —
/// "nothing changed", which this command's own comment calls overwhelmingly common — still paid the
/// full transfer. Comparing signatures FIRST turns that case into a few dozen bytes.
///
/// Over the PROJECTION, not the raw store, so a write that only touched `history` (which every write
/// touches) does not read as a change the page must re-render for.
pub(crate) fn page_signature(doc: &serde_json::Value) -> String {
    // `bsc_cli_util::vendored::sha256_hex` — the ONE content-hash form in this workspace, reused rather
    // than restated so a second spelling of "the hash of this thing" cannot drift from the first.
    bsc_cli_util::vendored::sha256_hex(serde_json::to_string(doc).unwrap_or_default().as_bytes())
}
